        panel.nameFieldStringValue = "\(item.name).\(GraphicPackage.fileExtension)"
        panel.beginSheetModal(for: window) { [weak self] response in
            guard response == .OK, let url = panel.url else { return }
            self?.exportChosen(to: url)
        }
    }

